static const pinyin_syl_t *pinyin_find(const char *s, int exact) {
    if (!s || !s[0]) return NULL;
    int lo = 0;
    int hi = (int) (sizeof(pinyin_syls) / sizeof(pinyin_syls[0]));
    size_t n = strlen(s);
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        int cmp = strcmp(pinyin_syls[mid].name, s);
        if (cmp < 0) lo = mid + 1;
        else hi = mid;
    }
    if (lo >= (int) (sizeof(pinyin_syls) / sizeof(pinyin_syls[0]))) return NULL;
    if (exact) return strcmp(pinyin_syls[lo].name, s) == 0 ? &pinyin_syls[lo] : NULL;
    return strncmp(pinyin_syls[lo].name, s, n) == 0 ? &pinyin_syls[lo] : NULL;
}

bool pinyin_is_prefix(const char *s) { return pinyin_find(s, 0) != NULL; }
bool pinyin_is_exact(const char *s) { return pinyin_find(s, 1) != NULL; }

int pinyin_candidate_count(const char *exact) {
    const pinyin_syl_t *syl = pinyin_find(exact, 1);
    return syl ? (int) syl->count : 0;
}

bool pinyin_candidate_utf8(const char *exact, int index, char out[4]) {
    const pinyin_syl_t *syl = pinyin_find(exact, 1);
    if (!syl || index < 0 || index >= (int) syl->count || !out) return false;
    memcpy(out, pinyin_chars + syl->offset + (unsigned) index * 3u, 3);
    out[3] = '\0';
    return true;
}
